/// 应用点击高亮效果（蓝色背景）
private func applyClickHighlight(at range: NSRange) {
    guard let textStorage = textStorage else { return }

    // 清除之前的点击高亮
    clearClickHighlight()

    // 保存原始颜色
    clickedWordRange = range
    if let color = textStorage.attribute(.foregroundColor, at: range.location, effectiveRange: nil) as? NSColor {
        clickedWordOriginalColor = color
    } else {
        clickedWordOriginalColor = DS.Colors.NS.textPrimary
    }

    // 添加高亮背景
    textStorage.addAttributes([
        .backgroundColor: DS.Colors.NS.accentPrimary.withAlphaComponent(0.3)
    ], range: range)
}

/// 清除点击高亮效果（供外部调用，如弹窗关闭时）
func clearClickHighlight() {
    guard let range = clickedWordRange,
          let textStorage = textStorage else { return }

    textStorage.removeAttribute(.backgroundColor, range: range)
    clickedWordRange = nil
    clickedWordOriginalColor = nil
}

